import {CustomerRecord} from './types';

/**
 * Resolves a conflict between the local copy and the server copy of a record.
 * Policy (DEC-0003): whole-record last-write-wins using server updatedAt.
 */
export function resolveConflict(local: CustomerRecord, server: CustomerRecord): CustomerRecord {
  if (server.deletedAt !== null) {
    return server;
  }
  return local.updatedAt > server.updatedAt ? local : server;
}

