import {resolveConflict} from './merge';
import {CustomerRecord, OutboxEntry} from './types';
import {api} from '../net/api';
import {db} from '../db/local';

export async function pushOutbox(entries: OutboxEntry[]): Promise<void> {
  for (const e of entries) {
    const res = await api.push(e);
    if (res.status === 409) {
      const merged = resolveConflict(await db.get(e.recordId), res.server as CustomerRecord);
      await db.put(merged);
    }
  }
}

