"""VAT computation. Prices are stored tax-exclusive in cents."""
from decimal import Decimal, ROUND_HALF_UP

VAT_RATES = {"DE": Decimal("0.19"), "FR": Decimal("0.20"), "NL": Decimal("0.21"), "IE": Decimal("0.23")}


def line_tax_cents(net_cents: int, country: str) -> int:
  """Per-line tax, rounded half-up to the cent (DEC-0010)."""
  rate = VAT_RATES.get(country, Decimal("0"))
  return int((Decimal(net_cents) * rate).quantize(Decimal("1"), rounding=ROUND_HALF_UP))

