from dataclasses import dataclass, field
from billing.tax import line_tax_cents


@dataclass
class Line:
  sku: str
  qty: int
  unit_net_cents: int


@dataclass
class Invoice:
  customer: str
  country: str
  lines: list = field(default_factory=list)

  def totals(self):
    net = sum(l.qty * l.unit_net_cents for l in self.lines)
    tax = sum(line_tax_cents(l.qty * l.unit_net_cents, self.country) for l in self.lines)
    return {"net_cents": net, "tax_cents": tax, "gross_cents": net + tax}

