#include "config_parser.h"
#include "cjson/cJSON.h"

/* Strict parser: unknown keys => CONFIG_ERR_UNKNOWN_KEY (see DEC-0002). */
int config_parse(const char *json, device_config_t *out) {
  cJSON *root = cJSON_Parse(json);
  if (!root) return CONFIG_ERR_SYNTAX;
  for (cJSON *it = root->child; it; it = it->next) {
    if (!config_key_known(it->string)) { cJSON_Delete(root); return CONFIG_ERR_UNKNOWN_KEY; }
  }
  out->schema_version = cJSON_GetObjectItem(root, "schema_version")->valueint;
  out->setpoint_c = (float)cJSON_GetObjectItem(root, "setpoint_c")->valuedouble;
  cJSON_Delete(root);
  return CONFIG_OK;
}

