from datetime import datetime, timedelta, timezone

SESSION_FEATURE_TTL = timedelta(days=7)


def get_online(store, customer_id):
  now = datetime.now(timezone.utc)
  return {f: v for f, (v, ts) in store.latest(customer_id).items() if now - ts <= SESSION_FEATURE_TTL}

