package routes

// SoftDelete marks a message deleted; the retention job purges after 30 days
// unless the account is under legal hold (DEC-0007).
func (h *Handler) SoftDelete(w http.ResponseWriter, r *http.Request) {
	h.store.SetDeletedAt(r.Context(), userID(r), msgID(r), h.clock.Now())
}

// SoftDeleteAll marks every message of the caller deleted.
func (h *Handler) SoftDeleteAll(w http.ResponseWriter, r *http.Request) {
	h.store.SetDeletedAtAll(r.Context(), userID(r), h.clock.Now())
}

