package realms

// AssignRealm places a new player in the least-populated realm in their region.
func AssignRealm(rs []*Realm, region string) *Realm {
	var best *Realm
	for _, r := range rs {
		if r.Region == region && !r.Full() && (best == nil || r.Population < best.Population) {
			best = r
		}
	}
	return best
}

