from datetime import datetime, timedelta, timezone
from server.leaderboards.base import Leaderboard


class WeeklyLeaderboard(Leaderboard):
  key_prefix = "lb:weekly"

  def period_start(self, now: datetime) -> datetime:
    now = now.astimezone(timezone.utc)
    monday = now - timedelta(days=now.weekday())
    return monday.replace(hour=0, minute=0, second=0, microsecond=0)


def current_key() -> str:
  return WeeklyLeaderboard().redis_key(datetime.now(timezone.utc))

