/** Locale resolution: exact match, then base language, then FALLBACK_DEFAULT (DEC-0006). */
export const FALLBACK_DEFAULT = 'en-US';

export const SUPPORTED_LOCALES = ['en-US', 'en-GB', 'fr-FR', 'de-DE', 'es-ES'];

export function resolve(requested: string): string {
  if (SUPPORTED_LOCALES.includes(requested)) return requested;
  const base = requested.split('-')[0];
  const sameLang = SUPPORTED_LOCALES.find(l => l.startsWith(base + '-'));
  return sameLang ?? FALLBACK_DEFAULT;
}

